import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify strong candidates based on t-statistics and AUC
    candidates = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'clinical':
            t_stat = feats.x[:, i].T @ feats.y / np.sqrt(np.var(feats.x[:, i]) * np.mean(feats.y) * (1 - np.mean(feats.y)))
            auc = np.corrcoef(feats.x[:, i], feats.y)[0, 1]
            candidates.append((fid, abs(t_stat), abs(auc)))

    candidates.sort(key=lambda x: x[1], reverse=True)
    top_candidates = [fid for fid, _, _ in candidates[:20]]

    # Remove near-duplicates
    to_remove = set()
    for i in range(len(top_candidates)):
        for j in range(i+1, len(top_candidates)):
            fid1, fid2 = top_candidates[i], top_candidates[j]
            if abs(np.corrcoef(feats.x[:, feats.column(fid1)], feats.x[:, feats.column(fid2)])[0,1]) > 0.6:
                to_remove.add(fid2)

    clean_candidates = [fid for fid in top_candidates if fid not in to_remove]

    # Check for interaction terms
    best_product = None
    best_p = 1.0

    for i, fid1 in enumerate(clean_candidates):
        for j, fid2 in enumerate(clean_candidates[i+1:], i+1):
            col1, col2 = feats.column(fid1), feats.column(fid2)
            prod = feats.x[:, col1] * feats.x[:, col2]

            # Fit logistic regression with product term
            X = np.column_stack([feats.x[:, col1], feats.x[:, col2], prod])
            model = LogisticRegression(fit_intercept=True, max_iter=1000).fit(X, feats.y)
            coef = model.coef_[0]

            # Use likelihood ratio test
            null_model = LogisticRegression(fit_intercept=True, max_iter=1000).fit(
                np.column_stack([feats.x[:, col1], feats.x[:, col2]]), feats.y)
            lr_stat = 2 * (model.score(X, feats.y) - null_model.score(np.column_stack([feats.x[:, col1], feats.x[:, col2]]), feats.y))
            p_val = 1 - stats.chi2.cdf(lr_stat, df=1)

            if p_val < best_p and p_val < 0.05:
                best_p = p_val
                best_product = (fid1, fid2)

    if best_product:
        return Design(
            drivers=(best_product[0],),
            columns=(best_product[0], best_product[1]),
            products=(best_product,),
            loadings={best_product[0]: 1.0}
        )

    # If no product found, return top single feature
    if clean_candidates:
        return Design(
            drivers=(clean_candidates[0],),
            columns=(clean_candidates[0],),
            products=(),
            loadings={clean_candidates[0]: 1.0}
        )

    return Design(drivers=(), columns=(), products=(), loadings={})

